SELECT count(*) FROM public.chartevents chartevents WHERE EXISTS (SELECT 1 FROM public.diagnoses_icd d, public.d_icd_diagnoses dd, public.admissions a, public.patients p, public.icustays i, public.transfers t, public.services s, public.outputevents oe, public.procedures_icd pr WHERE d.hadm_id = chartevents.hadm_id AND (d.icd_code = 'I10' OR d.icd_code = '4019') AND dd.icd_code = d.icd_code AND dd.icd_version = d.icd_version AND a.hadm_id = chartevents.hadm_id AND p.subject_id = a.subject_id AND i.stay_id = chartevents.stay_id AND t.hadm_id = a.hadm_id AND t.careunit = i.last_careunit AND s.hadm_id = a.hadm_id AND s.curr_service = 'MED' AND oe.stay_id = i.stay_id AND oe.itemid = 226559 AND pr.hadm_id = a.hadm_id);
